  for (const [word,pos,definition] of [["abate","verb","To become less intense, as wind, noise, or pain does when it eases."],["abrade","verb","To wear down a surface by rubbing or scraping it."],["accede","verb","To agree to a request or accept terms that someone else has proposed."],["accede","verb","To take up an office or title, especially a throne."],["acrid","adjective","Sharp enough in smell or taste to sting the nose or throat."],["adjoin","verb","To touch another place along a boundary."],["admit","verb","To acknowledge something that might be unwelcome or difficult to say."],["admit","verb","To allow someone or something to enter."],["afterimage","noun","A visual impression that lingers after its source has disappeared."],["aftertaste","noun","A flavor left in the mouth after swallowing."],["allege","verb","To state that something happened while leaving the claim open to proof."],["allude","verb","To refer indirectly to something the audience may recognize."],["ambiguous","adjective","Open to two or more plausible interpretations."],["ambivalent","adjective","Having competing feelings about the same person, choice, or event."],["amend","verb","To change a text, plan, or rule to correct or improve it."],["analogy","noun","A comparison that uses a shared relationship to explain an idea."],["anecdote","noun","A brief account of a particular incident, often told to illustrate a point."],["angular","adjective","Marked by sharp bends, corners, or pronounced bony outlines."],["anticipate","verb","To expect something ahead of time and sometimes prepare for it."],["antithesis","noun","A direct contrast, often expressed through similarly shaped phrases."],["aperture","noun","An opening through which light or something else can pass."],["arbitrary","adjective","Determined by personal choice or chance where a consistent rule might be expected."],["arc","noun","The course of change a character or a story follows."],["arc","verb","To move along a curved path."],["aside","noun","A remark set apart from the main speech, sometimes heard by the audience alone."],["assert","verb","To put a claim forward with confidence."],["assumption","noun","An idea accepted as a starting point before its truth has been established."],["attenuate","verb","To reduce strength, intensity, or concentration."],["backchannel","noun","A secondary route for communication outside the main conversation or official channel."],["backfill","verb","To supply missing information after the surrounding account has already been given."],["barbed","adjective","Containing a pointed criticism likely to hurt its recipient."],["beam","noun","A directed shaft of light or other energy."],["beam","verb","To smile in a way that plainly shows delight or pride."],["beat","noun","A pause or small shift of action that changes the timing of a scene."],["bleach","verb","To remove color or make something noticeably paler."],["blunt","adjective","Direct in expression, with little effort to soften the effect."],["blunt","verb","To make an edge less sharp or an impact less forceful."],["blur","verb","To make a boundary or distinction hard to perceive."],["body language","noun","Posture, movement, and facial expression through which people convey feelings or intentions."],["brittle","adjective","Likely to snap or fracture under pressure."],["brittle","adjective","Showing a strained composure that could give way abruptly."],["buckle","verb","To bend or collapse under a force too great to resist."],["buffer","verb","To hold data temporarily so it can be processed or played smoothly."],["cadence","noun","The pattern of stresses and pauses that gives a phrase its movement."],["calibrate","verb","To adjust an instrument or a judgment against a standard."],["canvas","noun","A sturdy woven cloth used for sails, shelters, or a painter\u2019s working surface."],["canvass","verb","To seek opinions, support, or votes by approaching people directly."],["causal","adjective","Concerning the way one event or condition brings about another."],["caveat","noun","A qualification that limits how far a claim or promise applies."],["chafe","verb","To irritate or wear skin through repeated rubbing."],["chafe","verb","To feel impatient or resentful under a restriction."],["characterization","noun","The choices through which a narrative gives a character recognizable traits and motives."],["chime","verb","To sound a clear, ringing note or series of notes."],["chronology","noun","The sequence in which events happened."],["cipher","noun","A system for transforming a message so it can be read only with the proper method or key."],["clank","verb","To make a heavy metallic sound when hard objects strike one another."],["clatter","verb","To make a rapid succession of hard, uneven impacts."],["climax","noun","The point of greatest intensity in a developing conflict."],["coarse","adjective","Made of relatively large or rough particles, fibers, or features."],["coherent","adjective","Organized so that the parts make sense together."],["coincidence","noun","An occurrence in which events align without an established causal connection."],["compress","verb","To fit material into a smaller space or a shorter span."],["concede","verb","To grant a point or yield a claim, often after some resistance."],["concrete","adjective","Specific enough to be pictured, sensed, or identified in a particular instance."],["confide","verb","To share a private thought or fact with someone trusted to receive it."],["connotation","noun","An association a word carries in addition to its direct meaning."],["consequence","noun","An outcome that follows from an action or condition."],["consistent","adjective","Compatible with a pattern or claim without contradicting it."],["conspicuous","adjective","Easy to notice because of position, appearance, or contrast."],["constraint","noun","A limit that narrows which actions or choices are possible."],["contradict","verb","To state or demonstrate something incompatible with another claim."],["contrast","noun","A difference made noticeable by placing two things in relation."],["corroborate","verb","To strengthen an account with additional evidence from another source."],["corrode","verb","To eat into a material gradually through chemical action."],["counterexample","noun","A case that shows a general claim fails under at least one of its stated conditions."],["counterfactual","adjective","Describing what might have happened under conditions different from those that actually held."],["credible","adjective","Giving sufficient reason to be taken seriously or believed."],["creep","verb","To move so slowly or quietly that the movement may escape notice."],["crisp","adjective","Cleanly defined in outline, sound, or timing."],["crux","noun","The particular point on which a question or difficulty turns."],["cue","noun","A signal that tells someone when to speak, act, or shift attention."],["curt","adjective","So brief and direct that the delivery may sound impatient."],["dapple","verb","To mark a surface with irregular patches of light, shadow, or color."],["deadpan","adjective","Delivered without visible amusement, even when the material is comic."],["deadline","noun","The latest time by which a task must be finished or submitted."],["deception","noun","An act or strategy that leads someone to believe something false."],["deduce","verb","To reach a conclusion that follows from stated premises."],["deflect","verb","To turn an object, question, or person\u2019s attention away from its course."],["delay","verb","To put off an event or cause it to happen later than expected."],["deliberate","adjective","Chosen with conscious intention."],["deliberate","verb","To weigh reasons or choices before reaching a decision."],["denotation","noun","The person, thing, class, or idea to which a word directly refers."],["depict","verb","To represent a person, place, or event in an image or in words."],["detail","noun","A small, distinct feature that helps make a larger whole recognizable."],["dialogue","noun","An exchange of speech between two or more voices."],["diffuse","verb","To spread through a space or among a group."],["diffuse","adjective","Spread over a wide area or extended beyond a clear focus."],["digital footprint","noun","The traces a person\u2019s activities leave in digital systems."],["dilate","verb","To widen or cause an opening to become wider."],["dissonance","noun","A tension produced when sounds, ideas, or impressions fit uneasily together."],["distant","adjective","Separated by considerable space or by a lack of emotional closeness."],["distract","verb","To draw attention away from its current object."],["dither","verb","To hesitate between choices without settling on an action."],["diverge","verb","To move apart from a shared point, direction, or position."],["double meaning","noun","A second interpretation that the same words can support alongside the first."],["draft","noun","A version of a text still open to change."],["draft","noun","A current of air moving through a place."],["drift","verb","To move with little evident effort or deliberate control."],["drone","verb","To produce a low, sustained sound with little variation."],["dry","adjective","Understated in humor, often inviting the listener to notice the joke independently."],["echo","verb","To repeat a sound, image, or idea across a distance or a passage."],["edge","verb","To move by small, cautious increments."],["elliptical","adjective","Leaving steps or details unstated so that the reader must supply them."],["embed","verb","To set something firmly within surrounding material or a larger structure."],["empathy","noun","The capacity to apprehend another person\u2019s feelings or perspective."],["enact","verb","To carry something into action or give it a performed form."],["encounter","noun","A meeting or confrontation, especially one whose outcome is uncertain."],["envisage","verb","To form a mental picture of an event, object, or possibility."],["equivocal","adjective","Capable of supporting competing interpretations or withholding a clear commitment."],["erode","verb","To wear away gradually through repeated exposure or pressure."],["evidence","noun","Information that bears on whether a claim is true."],["evoke","verb","To bring a feeling, image, or memory into the reader\u2019s or listener\u2019s mind."],["excerpt","noun","A portion selected from a longer work."],["expanse","noun","An extended area perceived as open or largely uninterrupted."],["explicit","adjective","Stated directly enough that the intended point need not be inferred."],["exposition","noun","The presentation of information a reader needs to understand a subject or a story."],["facet","noun","One distinct aspect of something that can be considered from several sides."],["faint","adjective","Near the threshold of perception in sound, light, smell, or detail."],["false start","noun","An opening attempt that breaks off before the intended action gets underway."],["falter","verb","To lose steadiness, confidence, or momentum without necessarily stopping."],["feedback loop","noun","A cycle in which the result of a process influences what the process does next."],["focalization","noun","The way a narrative filters information through a particular standpoint or perceiving consciousness."],["foreshadow","verb","To introduce a detail whose significance becomes clearer through later events."],["frame","verb","To present information from an angle that shapes how others understand it."],["fray","verb","To loosen into strands at an edge or weaken under continued strain."],["friction","noun","Resistance to movement between surfaces, or tension between people or interests."],["glance","verb","To direct the eyes toward something briefly."],["glare","noun","Intense light that makes seeing uncomfortable or difficult."],["glare","verb","To look at someone with a fixed expression of anger or hostility."],["glaze","verb","To cover with a thin, smooth layer that changes a surface\u2019s sheen or color."],["gleam","verb","To give off or reflect a small, distinct light."],["glimmer","verb","To show a weak or intermittent light that can still be made out."],["glimpse","noun","A brief or partial view, often too short for close inspection."],["grate","verb","To make a harsh scraping sound by rubbing hard surfaces together."],["grit","noun","Small, rough particles that can be felt between surfaces."],["gruff","adjective","Rough and abrupt in voice or manner."],["haptic","adjective","Relating to touch or to sensations a device produces through contact."],["hinge","verb","To depend decisively on a particular fact, choice, or condition."],["hoarse","adjective","Rough or breathy in voice, especially after strain or illness."],["implication","noun","A consequence or suggestion that follows from what has been said or shown."],["imply","verb","To communicate indirectly through wording, circumstances, or conduct."],["infer","verb","To draw a conclusion from clues, evidence, or reasoning."],["intent","noun","The purpose a person means an action or expression to serve."],["juxtapose","verb","To place things close enough together for their relationship to become noticeable."],["motif","noun","A recurring image, phrase, or situation that gathers significance across a work."],["nuance","noun","A small distinction in meaning, tone, or effect that changes how something is understood."],["perspective","noun","The position or background from which someone perceives and interprets events."],["podcast","noun","A series of spoken or audio programs made available to listeners on demand."],["register","noun","A variety of language suited to a particular setting, audience, or relationship."],["screenshot","noun","An image capturing what a screen displays at a particular moment."],["subtext","noun","An implication or emotional current communicated beneath the surface of what is said."],["timestamp","noun","A recorded date or time associated with a message, file, observation, or event."],["unreliable narrator","noun","A storyteller whose account gives the reader reasons to question its accuracy or interpretation."],["voice","noun","The distinctive verbal presence created by a speaker\u2019s or writer\u2019s choices."],["wince","verb","To make a brief involuntary movement or expression in response to pain or embarrassment."]]) add(word,pos,definition,'Diction editorial glossary');
